          window: window,
          settings: settings,
          hysteresis: hysteresis,
        ),
        isTrue,
      );
      // Over the hard line the hysteresis never mutes.
      hysteresis.recordRun();
      expect(
        softTriggerReached(
          tokens: hard + 1,
          window: window,
