      pass: 2,
      tokensBefore: 105866,
      tokensAfter: 59496,
      fallback: 'smol',
      ok: true,
      summary:
          '## Goal\n- long internal checkpoint notes\n'
          'hidden segments (compact_expand reopens any id)',
      hiddenRecords: 42,
      summarizedMessages: 17,
    );

    test('the auto report is the single marker line by default', () {
